/** Offline evaluator for an actual graph-first recovery observation. Never authenticates or calls a host/database. */
import {decodeScope1Register,decodeScope1Report} from '../../apps/site-web/src/lib/m78-api';
import {decodeCorporateRegister} from '../../apps/site-web/src/lib/m71-api';
import {decodeGasRegister} from '../../apps/site-web/src/lib/m73-api';
import {decodeMobileRegister} from '../../apps/site-web/src/lib/m74-api';
import {decodeFleetRegister} from '../../apps/site-web/src/lib/m75-api';
import {decodeGeneratorRegister} from '../../apps/site-web/src/lib/m76-diesel-api';
import {decodeStationaryRegister} from '../../apps/site-web/src/lib/m76-api';
import {decodeFugitiveRegister} from '../../apps/site-web/src/lib/m77-api';
import {m78CanonicalJson as canonical,parseM78Json,validateM78InventorySave,validateM78ProcessSave,validateM78Report,validateM78Review} from '../../packages/neuvetra-database/src/m78-validation';
import {validateM71Save,validateM71Review} from '../../packages/neuvetra-database/src/m71-validation';
import {validateM73Save,validateM73Review} from '../../packages/neuvetra-database/src/m73-validation';
import {validateM74Save,validateM74Review} from '../../packages/neuvetra-database/src/m74-validation';
import {validateM75Save,validateM75Review} from '../../packages/neuvetra-database/src/m75-validation';
import {validateM76Save,validateM76Review} from '../../packages/neuvetra-database/src/m76-validation';
import {validateM76DieselSave,validateM76DieselReview} from '../../packages/neuvetra-database/src/m76-diesel-validation';
import {validateM77SourceSave,validateM77PopulationSave,validateM77Review} from '../../packages/neuvetra-database/src/m77-validation';
import {readM78ContinuationJournal,m78VerifiedIdentity} from '../../tools/staging/check-m78-continuation';
import {preservesM77History} from '../../tools/staging/check-m77-hosted';
import {verifyExerciseFailure} from './m78-continuation4-exercise-failure-qa-check';
import {M78_READONLY_RECOVERY2_LIMITS,M78_READONLY_RECOVERY2_PATHS,evaluateM78ReadonlyRecovery2Capture,reconstructM78ReadonlyRecovery2Artifacts} from '../../tools/staging/check-m78-continuation4-readonly-recovery2';
const sha=(value:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(value).digest('hex');
const check:(value:unknown,message:string)=>asserts value=(value,message)=>{if(!value)throw Error(message)};
const same=(a:unknown,b:unknown)=>canonical(a)===canonical(b);
type FailureInputs=Parameters<typeof verifyExerciseFailure>[0];
export type Recovery2ReviewAdmission={journalSha256:string;journalHead:string;diagnosticsSha256:string;diagnosticsHead:string;rawCaptureSha256:string;rawCaptureHead:string;observationSha256:string;currentSourceGateSha256:string};

function chain(text:string,profile:string){check(text.endsWith('\n'),'newline');let previous:string|null=null;return text.trimEnd().split('\n').map((line,index)=>{const event=JSON.parse(line),{sha256:hash,...body}=event;check(event.sequence===index+1&&event.previousSha256===previous&&event.profile===profile&&sha(canonical(body))===hash,'event chain');previous=hash;return event})}
function captureBytes(event:any){check(event.encoding==='base64','base64 raw capture');return Uint8Array.from(Buffer.from(event.body,'base64'))}
function captureText(event:any){return new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(captureBytes(event))}
function captureJson(event:any){return parseM78Json(captureText(event),M78_READONLY_RECOVERY2_LIMITS.responseBytes)}
function graphObjects(value:unknown,result:any[]=[]){if(!value||typeof value!=='object')return result;if(Array.isArray(value)){for(const item of value)graphObjects(item,result);return result}const object=value as Record<string,unknown>;result.push(object);for(const item of Object.values(object))graphObjects(item,result);return result}
function identitySet(value:unknown){const result=new Map<string,unknown>();for(const object of graphObjects(value))try{const identity=m78VerifiedIdentity(object);if(identity.versionSha256||identity.decisionSha256||identity.reportSha256)result.set(canonical(identity),identity)}catch{}return result}
function preservesBytes(before:any,after:any,label:string){for(const family of Object.keys(before))for(const[key,value]of Object.entries(before[family]))check(same(after[family]?.[key],value),`${label} retained ${family}/${key}`)}
function validateIntent(name:string,value:unknown){if(name==='m78_factual_corporate_successor')return validateM71Save(value);if(name==='m78_corporate_separate_review')return validateM71Review(value);if(name.startsWith('m78_rebind_natural_gas_'))return validateM73Save(value);if(name.startsWith('m78_review_natural_gas_'))return validateM73Review(value);if(name.startsWith('m78_rebind_mobile_diesel_'))return validateM74Save(value);if(name.startsWith('m78_review_mobile_diesel_'))return validateM74Review(value);if(name.startsWith('m78_rebind_stationary_diesel_'))return validateM76DieselSave(value);if(name.startsWith('m78_review_stationary_diesel_'))return validateM76DieselReview(value);if(name.startsWith('m78_rebind_fugitive_'))return validateM77SourceSave(value);if(name.startsWith('m78_review_fugitive_'))return validateM77Review(value);if(name==='m78_rebind_fleet_discovery')return validateM75Save(value);if(name==='m78_review_fleet_discovery')return validateM75Review(value);if(name==='m78_rebind_stationary_discovery')return validateM76Save(value);if(name==='m78_review_stationary_discovery')return validateM76Review(value);if(name==='m78_rebind_fugitive_discovery')return validateM77PopulationSave(value);if(name==='m78_review_fugitive_discovery')return validateM77Review(value);if(name==='m78_complete_process_discovery')return validateM78ProcessSave(value);if(name==='m78_current_inventory_successor')return validateM78InventorySave(value);if(name.includes('report'))return validateM78Report(value);if(name==='m78_process_separate_review'||name==='m78_inventory_separate_review')return validateM78Review(value);throw Error('unknown recipe validator '+name)}

export function verifyRecovery2TransportEvidence(journalText:string,diagnosticText:string,rawCaptureText:string,admission:Pick<Recovery2ReviewAdmission,'journalSha256'|'journalHead'|'diagnosticsSha256'|'diagnosticsHead'|'rawCaptureSha256'|'rawCaptureHead'>){
 check(sha(journalText)===admission.journalSha256&&sha(diagnosticText)===admission.diagnosticsSha256&&sha(rawCaptureText)===admission.rawCaptureSha256,'recovery2 transport pins');const journal=chain(journalText,'m78-continuation4-readonly-recovery2-v1'),diagnostics=chain(diagnosticText,'m78-continuation4-readonly-recovery2-diagnostic-v1'),captures=evaluateM78ReadonlyRecovery2Capture(rawCaptureText);check(journal.at(-1)?.sha256===admission.journalHead&&diagnostics.at(-1)?.sha256===admission.diagnosticsHead&&captures.at(-1)?.sha256===admission.rawCaptureHead,'recovery2 heads');check(journal[0]?.kind==='attempt_started'&&journal.filter(event=>event.kind==='attempt_started').length===1&&journal.filter(event=>event.kind==='attempt_finished').length===1&&!journal.some(event=>event.kind.startsWith('post_')||event.kind==='exercise_complete'),'recovery2 main shape');const finish=journal.at(-1)!;check(finish.kind==='attempt_finished'&&finish.data.status==='passed'&&finish.data.applicationPostRequests===0&&finish.data.allCreatedAuthSessionsClosed===true&&finish.data.unknownAuthSessions===0&&finish.data.diagnosticsHealthy===true,'recovery2 terminal');
 const roles=['manager1','manager2','member','outsider'];check(same(journal.filter(event=>event.kind==='auth_intent').map(event=>event.data.role),roles)&&same(journal.filter(event=>event.kind==='auth_outcome').map(event=>event.data.role),roles)&&same(journal.filter(event=>event.kind==='logout_intent').map(event=>event.data.role),roles)&&same(journal.filter(event=>event.kind==='logout_outcome').map(event=>event.data.role),roles),'exact main auth role sequence');for(const role of roles){const authIntent=journal.filter(event=>event.kind==='auth_intent'&&event.data.role===role),authOutcome=journal.filter(event=>event.kind==='auth_outcome'&&event.data.role===role),logoutIntent=journal.filter(event=>event.kind==='logout_intent'&&event.data.role===role),logoutOutcome=journal.filter(event=>event.kind==='logout_outcome'&&event.data.role===role);check(authIntent.length===1&&authOutcome.length===1&&authOutcome[0]!.data.status===200&&authOutcome[0]!.data.subjectMatched===true&&authOutcome[0]!.data.sessionCreationUncertain===false,`known auth ${role}`);check(logoutIntent.length===1&&logoutOutcome.length===1&&logoutOutcome[0]!.data.status===204,`closed auth ${role}`)}
 const requests=new Map<number,any>();for(const event of diagnostics){if(event.kind==='request_intent'){check(event.data.ordinal===requests.size+1&&['GET','POST'].includes(event.data.method),'diagnostic ordinal/method');if(event.data.route.startsWith('application:'))check(event.data.method==='GET','zero-write application diagnostic');else check(event.data.method==='POST'&&['auth:/auth/v1/token','auth:/auth/v1/logout'].includes(event.data.route),'fixed auth diagnostic');requests.set(event.data.ordinal,{intent:event,outcome:null})}else if(event.kind==='response_headers'||event.kind==='request_error'){const pair=requests.get(event.data.ordinal);check(pair&&!pair.outcome,'paired diagnostic');check(event.kind==='response_headers','no recovery2 request error');pair.outcome=event}else check(event===diagnostics.at(-1)&&event.kind==='phase_finished','diagnostic event kind')};const pairs=[...requests.values()];check(pairs.every(pair=>pair.outcome),'all diagnostics paired');const tokenPairs=pairs.filter(pair=>pair.intent.data.route==='auth:/auth/v1/token'),logoutPairs=pairs.filter(pair=>pair.intent.data.route==='auth:/auth/v1/logout'),applicationPairs=pairs.filter(pair=>pair.intent.data.route.startsWith('application:'));check(tokenPairs.length===8&&tokenPairs.every(pair=>pair.outcome.data.status===200)&&logoutPairs.length===8&&logoutPairs.every(pair=>pair.intent.data.logoutScope==='local'&&pair.outcome.data.status===204),'main plus legacy local auth closure');check(applicationPairs.length>=40&&applicationPairs.every(pair=>[200,401,403].includes(pair.outcome.data.status)),'bounded application GET evidence');const initialTokens=pairs.slice(0,4),mainReads=pairs.slice(4,20),scopeRoute='application:/workspace-api/workspace/:id/scope1-inventory';check(initialTokens.every(pair=>pair.intent.data.route==='auth:/auth/v1/token'&&pair.outcome.data.status===200),'four main auth tokens before reads');check(mainReads.length===16&&same(mainReads.slice(0,4).map(pair=>pair.intent.data.route),[scopeRoute,scopeRoute,scopeRoute,scopeRoute])&&same(mainReads.slice(0,4).map(pair=>pair.outcome.data.status),[403,401,200,200]),'exact scope1 authorization/read prefix');const upstream=['corporate-inventories','stationary-natural-gas','mobile-diesel','controlled-fleet','stationary-diesel','stationary-equipment','fugitive-sources'];check(same(mainReads.slice(4,11).map(pair=>pair.intent.data.route),upstream.map(family=>`application:/workspace-api/workspace/:id/${family}`))&&mainReads.slice(4,11).every(pair=>pair.outcome.data.status===200),'exact seven upstream reads');check(mainReads.slice(11).length===5&&mainReads.slice(11).every(pair=>pair.outcome.data.status===200&&pair.intent.data.route.includes('/reports/')),'five exact full scope1 report reads');const artifacts=applicationPairs.slice(16,40),expectedArtifacts=(family:string,count:number)=>Array.from({length:count},()=>['download','snapshot','proof'].map(operation=>`application:/workspace-api/workspace/:id/${family}/:id/reports/:id/${operation}`)).flat(),artifactRoutes=[...expectedArtifacts('controlled-fleet',3),...expectedArtifacts('stationary-equipment',5)];check(same(artifacts.map(pair=>pair.intent.data.route),artifactRoutes)&&artifacts.every(pair=>pair.outcome.data.status===200),'exact 24 roster artifact reads');check(captures.length===applicationPairs.length,'one raw capture per application response');for(let index=0;index<captures.length;index++){const capture=captures[index]!,pair=applicationPairs[index]!;check(capture.requestOrdinal===pair.intent.data.ordinal&&capture.route===pair.intent.data.route&&capture.responseStatus===pair.outcome.data.status,'capture diagnostic binding')}check(finish.data.requests===requests.size&&diagnostics.at(-1)!.data.requests===requests.size,'terminal request counts');check(diagnostics.at(-1)!.data.status==='passed'&&diagnostics.at(-1)!.data.applicationPostRequests===0&&diagnostics.at(-1)!.data.allCreatedAuthSessionsClosed===true&&diagnostics.at(-1)!.data.unknownAuthSessions===0&&diagnostics.at(-1)!.data.diagnosticsHealthy===true,'diagnostic closure');return{journal,diagnostics,requests,captures};
}
export function verifyExactAddedTypedRecords(beforeGraph:unknown,afterGraph:unknown,verifiedIdentities:unknown[]){const before=identitySet(beforeGraph),after=identitySet(afterGraph),added=[...after.keys()].filter(key=>!before.has(key)).sort(),verified=verifiedIdentities.map(value=>canonical(value)).sort();check(added.length===37&&same(added,verified),'exactly37 added typed records');return added}
export function verifyRecovery2ObservationBinding(journal:any[],observationText:string,rawCaptureSha256:string,currentSourceGateSha256:string){const started=journal[0],observed=journal.find(event=>event.kind==='recovery2_observed');check(started?.kind==='attempt_started'&&started.data.currentSourceGateSha256===currentSourceGateSha256&&observed&&observed.data.observationSha256===sha(observationText)&&observed.data.rawCaptureSha256===rawCaptureSha256&&observed.data.applicationPostRequests===0&&observed.data.allMainSessionsClosed===true&&observed.data.allLegacySessionsClosed===true,'journal observation/source binding');return observed}

export async function verifyM78Continuation4ReadonlyRecovery2(inputs:FailureInputs&{failureReviewText:string;failedRecoveryJournalText:string;failedRecoveryDiagnosticText:string;failedRecoveryReviewText:string;recoveryJournalText:string;recoveryDiagnosticText:string;recoveryRawCaptureText:string;observationText:string;currentSourceGateText:string},admission:Recovery2ReviewAdmission){
 const failure=await verifyExerciseFailure(inputs);check(sha(inputs.failureReviewText)==='a97a84ca66ed696a348c8c8a5ecaf65e36ca4eb311803b6f2ecccebf9d16c573','failure review pin');const failureReview=JSON.parse(inputs.failureReviewText);check(failureReview.status===failure.status&&failureReview.exerciseAccepted===false,'failed exercise remains unaccepted');
 check(sha(inputs.failedRecoveryJournalText)==='0c2062c12db60f0e65c21f0fcc17122a95a11ba689d04f18c51c0652f887aca8'&&sha(inputs.failedRecoveryDiagnosticText)==='e2e56cc5b3220b1d138023e945e38c9d2dfeca26a15bcd4a35b2cd71d33ff57c'&&sha(inputs.failedRecoveryReviewText)==='7e46ba485e77c132113ac78d8dd4d0ef3ffb440f3a790afcdaa7874532923cac','failed recovery2 input pins');const failedReview=JSON.parse(inputs.failedRecoveryReviewText);check(failedReview.status==='m78_readonly_recovery_failure2_independently_reconciled'&&failedReview.materialFindingsOpen===0&&failedReview.actualRecoveryAccepted===false,'failed recovery2 remains unaccepted');
 check(sha(inputs.observationText)===admission.observationSha256&&sha(inputs.currentSourceGateText)===admission.currentSourceGateSha256,'recovery pins');const{journal,diagnostics,requests,captures}=verifyRecovery2TransportEvidence(inputs.recoveryJournalText,inputs.recoveryDiagnosticText,inputs.recoveryRawCaptureText,admission),observation=JSON.parse(inputs.observationText),sourceGate=JSON.parse(inputs.currentSourceGateText);verifyRecovery2ObservationBinding(journal,inputs.observationText,admission.rawCaptureSha256,admission.currentSourceGateSha256);
 check(observation.status==='m78_continuation4_readonly_recovery2_observed'&&observation.profile==='m78-continuation4-readonly-recovery2-observation-v1'&&observation.failedMainSha256==='44e7bec2d2e6a4a554de6ba23775150bfdf29582fd69ff12bc6cfbc73770ba8b'&&observation.failedDiagnosticsSha256==='d77a8f58ec92a0642a5b0b4a91113920ccd4013b9bcfee9a9c7e5de90d93e651'&&observation.failedRecoverySha256==='0c2062c12db60f0e65c21f0fcc17122a95a11ba689d04f18c51c0652f887aca8'&&observation.failedRecoveryDiagnosticsSha256==='e2e56cc5b3220b1d138023e945e38c9d2dfeca26a15bcd4a35b2cd71d33ff57c'&&observation.failedRecoveryReviewSha256===sha(inputs.failedRecoveryReviewText)&&observation.applicationPostRequests===0&&observation.scope1FullReportReads===5&&observation.rosterArtifactReads===24,'recovery2 observation');check(sourceGate.status==='m78_continuation4_readonly_recovery2_source_admitted'&&sourceGate.failedRecoverySha256===observation.failedRecoverySha256&&sourceGate.failedRecoveryDiagnosticsSha256===observation.failedRecoveryDiagnosticsSha256&&sourceGate.failedRecoveryReviewSha256===observation.failedRecoveryReviewSha256&&sourceGate.runtime&&/^[a-f0-9]{40}$/.test(sourceGate.runtime.commit)&&typeof sourceGate.runtime.deploymentId==='string'&&/^sha256:[a-f0-9]{64}$/.test(sourceGate.runtime.imageDigest)&&same(sourceGate.sourcePins,observation.currentSourcePins)&&observation.currentSourceGateSha256===admission.currentSourceGateSha256,'fresh source/runtime gate');check(observation.historicalSourcePins.length===173&&!same(observation.historicalSourcePins,observation.currentSourcePins),'separate historical/current source closure');check(observation.rawCaptureSha256===admission.rawCaptureSha256&&observation.rawCaptureHead===admission.rawCaptureHead&&observation.rawCaptureEvents===captures.length&&Buffer.byteLength(inputs.recoveryRawCaptureText)<=M78_READONLY_RECOVERY2_LIMITS.rawCaptureBytes,'closed raw capture binding');
 const first=JSON.parse(inputs.mainText.split('\n')[0]!),events=readM78ContinuationJournal(inputs.mainText,first.workspaceId),baselineEvent=events.find(event=>event.kind==='baseline')!;check(same(captureJson(captures[2]),observation.scope1)&&same(captureJson(captures[3]),observation.scope1),'captured manager/member graph binding');const baselineDecoded=await decodeScope1Register(baselineEvent.data.scope1,first.workspaceId),decoded=await decodeScope1Register(observation.scope1,first.workspaceId);check(same(decoded,observation.scope1),'production decoded fresh graph');const families=['corporate','gas','mobile','fleet','diesel','equipment','fugitive']as const;for(let index=0;index<families.length;index++)check(same(captureJson(captures[4+index]),observation.registers[families[index]!]),'captured register '+families[index]);const decodedRegisters={corporate:await decodeCorporateRegister(observation.registers.corporate,first.workspaceId),gas:await decodeGasRegister(observation.registers.gas,first.workspaceId),mobile:await decodeMobileRegister(observation.registers.mobile,first.workspaceId),fleet:await decodeFleetRegister(observation.registers.fleet,first.workspaceId),diesel:await decodeGeneratorRegister(observation.registers.diesel,first.workspaceId),equipment:await decodeStationaryRegister(observation.registers.equipment,first.workspaceId),fugitive:await decodeFugitiveRegister(observation.registers.fugitive,first.workspaceId)};check(same(decodedRegisters,observation.registers),'production decoded seven upstream registers');const decodedFullReports:Record<string,unknown>={};for(let index=11;index<16;index++){const raw=captureJson(captures[index]),report=await decodeScope1Report(raw,first.workspaceId);check(same(raw,observation.fullReports[report.id])&&!decodedFullReports[report.id],'captured full report binding');decodedFullReports[report.id]=report}check(Object.keys(decodedFullReports).length===5&&same(Object.keys(decodedFullReports).sort(),Object.keys(observation.fullReports).sort()),'five captured full reports');
 const captureBySequence=new Map(captures.map((event:any)=>[event.sequence,event])),used=new Set<number>(),rosterArtifacts:any={fleet:{},equipment:{}};for(const[family,base]of[['fleet','controlled-fleet'],['equipment','stationary-equipment']]as const){const references=observation.rosterArtifacts?.[family];check(references&&same(Object.keys(references).sort(),observation.registers[family].reports.map((report:any)=>report.id).sort()),family+' artifact reference keys');for(const report of observation.registers[family].reports){const reference=references[report.id],read=(name:'htmlCapture'|'snapshotCapture'|'proofCapture',operation:string)=>{const sequence=reference?.[name],event=captureBySequence.get(sequence);check(Number.isInteger(sequence)&&!used.has(sequence)&&event&&event.responseStatus===200&&event.route===`application:/workspace-api/workspace/:id/${base}/:id/reports/:id/${operation}`&&event.headers['cache-control']?.includes('no-store'),family+' '+operation+' capture');used.add(sequence);return event};const html=read('htmlCapture','download'),snapshot=read('snapshotCapture','snapshot'),proof=read('proofCapture','proof');rosterArtifacts[family][report.id]={html:captureText(html),snapshotJson:captureText(snapshot),proofEnvelope:captureJson(proof),htmlCapture:html.sequence,snapshotCapture:snapshot.sequence,proofCapture:proof.sequence}}}check(used.size===24,'exact24 referenced roster captures');const reconstructed=await reconstructM78ReadonlyRecovery2Artifacts(decoded,decodedRegisters,decodedFullReports,rosterArtifacts);check(same(reconstructed.downloads,observation.downloads)&&same(reconstructed.m78bytes,observation.m78bytes),'independently reconstructed retained artifacts');const capturedBytes=captures.reduce((total:number,event:any)=>total+event.byteLength,0);check(Number.isSafeInteger(observation.retainedResponseBytes)&&observation.retainedResponseBytes===capturedBytes&&observation.retainedResponseBytes>0&&observation.retainedResponseBytes<=M78_READONLY_RECOVERY2_LIMITS.retainedResponseBytes&&observation.retainedResponseByteLimit===M78_READONLY_RECOVERY2_LIMITS.retainedResponseBytes,'bounded retained response bytes');
 check(decoded.reconciliation.status==='reconciled_bounded_synthetic'&&decoded.reconciliation.totals?.company.kgCo2eExact==='126850.17632025'&&decoded.reconciliation.sourceUnion.length===10&&decoded.process.versions.length===1&&decoded.inventory.versions.length===2&&decoded.process.reports.length===2&&decoded.inventory.reports.length===3&&decoded.process.versions[0]!.review?.decision==='accepted_bounded_process_screen'&&decoded.inventory.versions[0]!.review===null&&decoded.inventory.versions[1]!.review?.decision==='accepted_bounded_inventory','exact final totals/history/reviews/reports');
 check(same(decoded.inventory.versions[0],baselineDecoded.inventory.versions[0]),'initial inventory immutable');preservesM77History(baselineEvent.data.registers,decodedRegisters);preservesBytes(baselineEvent.data.downloads,observation.downloads,'prior downloads');preservesBytes(baselineEvent.data.m78bytes,observation.m78bytes,'prior m78 bytes');check(same(baselineEvent.data.legacy,observation.legacy),'unchanged legacy');
 const expectedNames=['m78_initial_unreviewed_report','m78_factual_corporate_successor','m78_corporate_separate_review',...baselineDecoded.proof.sourceVersions.flatMap(({family,version}:any)=>[`m78_rebind_${family}_${version.activity.binding.sourceId}`,`m78_review_${family}_${version.activity.binding.sourceId}`]),'m78_rebind_fleet_discovery','m78_review_fleet_discovery','m78_rebind_stationary_discovery','m78_review_stationary_discovery','m78_rebind_fugitive_discovery','m78_review_fugitive_discovery','m78_complete_process_discovery','m78_process_unreviewed_report','m78_process_separate_review','m78_process_reviewed_report','m78_current_inventory_successor','m78_inventory_unreviewed_report','m78_inventory_separate_review','m78_inventory_reviewed_report'];check(expectedNames.length===37,'exact37 names');const recipe=events.filter(event=>event.mode==='exercise'&&['post_intent','post_outcome','post_verified'].includes(event.kind)),operations=new Map<string,{intent:any;verified:any}>(),keys=new Set<string>();for(let index=0;index<37;index++){const[intent,outcome,verified]=recipe.slice(index*3,index*3+3),name=expectedNames[index]!;check(intent.data.name===name&&outcome.data.name===name&&verified.data.name===name&&outcome.data.status===201&&outcome.data.responseSha256===verified.data.responseSha256,`recipe triple ${index+1}`);validateIntent(name,intent.data.request);check(!keys.has(intent.data.request.idempotencyKey),'unique idempotency');keys.add(intent.data.request.idempotencyKey);operations.set(name,{intent,verified})}
